import{_ as a,o as s,c as i,a5 as r}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Persistencia y recuperación duradera","description":"","frontmatter":{"title":"Persistencia y recuperación duradera","docId":"developer.storage","translationKey":"developer.storage","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","translationRevision":"896bd5209b72c3b0f4f847f32efb8af9808c3dfc098053237a901a0a6645121b","order":60},"headers":[],"relativePath":"es/developer/storage.md","filePath":"es/developer/storage.md","lastUpdated":1794611623000}'),o={name:"es/developer/storage.md"};function t(n,e,d,l,c,p){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="persistence-and-durable-recovery" tabindex="-1">Persistencia y recuperación duradera <a class="header-anchor" href="#persistence-and-durable-recovery" aria-label="Permalink to &quot;Persistencia y recuperación duradera {#persistence-and-durable-recovery}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Modifica los datos persistentes mediante su servicio propietario y conserva resultados recuperables. Utiliza un perfil desechable, detén su host antes de copiar bases de datos y lee los <a href="./control-api.html">metadatos de control</a> antes de editar recursos versionados. <code>TIKTOOLS_HOME</code> selecciona la raíz; <code>AppPaths</code> resuelve sus datos y almacenes privados.</p><h2 id="identify-the-store" tabindex="-1">Identificar el almacén <a class="header-anchor" href="#identify-the-store" aria-label="Permalink to &quot;Identificar el almacén {#identify-the-store}&quot;">​</a></h2><p><code>crates/tiktools-core/src/paths.rs</code> define <code>data/tiktok-points.db</code>, <code>data/tiktok-automation.db</code> y <code>data/tiktok-analytics.db</code>. Los módulos de servicio SQLite poseen sus esquemas. Puntos/espectadores y definiciones de automatización tienen registros de negocio separados; analítica utiliza otra base, ausente en los diagramas antiguos de dos bases.</p><p>El inicio puede copiar bases heredadas del checkout a los datos de la plataforma únicamente si el destino no existe. Nunca reemplaza un destino existente. Las definiciones JSON siguen siendo legibles durante cambios de ejecución nativa. No implementes migraciones borrando perfiles ni reescribiendo tablas desde Vue.</p><h2 id="make-a-recoverable-change" tabindex="-1">Crear un cambio recuperable <a class="header-anchor" href="#make-a-recoverable-change" aria-label="Permalink to &quot;Crear un cambio recuperable {#make-a-recoverable-change}&quot;">​</a></h2><ol><li>Localiza la transacción del servicio y sus pruebas de esquema y migración.</li><li>Guarda el cambio, su revisión y la reserva del diario o bandeja de salida en una misma transacción cuando ese dominio lo admita.</li><li>Conserva las revisiones de borrado. Reutilizar un identificador no debe aceptar una edición anterior a su eliminación.</li><li>Publica invalidaciones confirmadas mediante la bandeja existente; reintentar su entrega no debe repetir la acción original.</li><li>Tras una interrupción, abre el mismo perfil privado y resuelve la orden original antes de intentar otra mutación.</li></ol><p>Comprobaciones de lectura contra un host de prueba activo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Los flujos duraderos de workflows, puntos y diarios del propietario conservan resultados originales tras reiniciar. Un recibo describe una orden histórica; consulta aparte el estado actual. Los almacenes Cloud añaden particiones por origen/cuenta y comprobaciones de generación sin reemplazar la autoridad SQLite local. La cobertura no es idéntica para todos los efectos externos o dominios.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Conserva juntos SQLite y sus archivos WAL/SHM al crear una copia fuera de línea. Un tiempo de espera de la interfaz no demuestra reversión. Ante <code>revision_conflict</code>, guarda el borrador y compara una lectura reciente. Para efectos inciertos, inspecciona su registro en lugar de repetir el feed. Consulta la <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/paths.rs" target="_blank" rel="noreferrer">autoridad de rutas</a> y la <a href="./cloud.html">recuperación Cloud</a>.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Consulta rutas antes de experimentar/copiar con <code>tiktools api call system.info --json</code>. <code>TIKTOOLS_HOME</code> elige raíz; <code>TIKTOOLS_DATA_DIR</code>, <code>TIKTOOLS_PLUGINS_DIR</code>, <code>TIKTOOLS_PLUGIN_DATA_DIR</code>, <code>TIKTOOLS_PLUGIN_STORE_DIR</code>, <code>TIKTOOLS_LOG_DIR</code> y <code>TIKTOOLS_TEMP_DIR</code> sustituyen sus directorios derivados. Los valores relativos parten del directorio de lanzamiento. Una raíz aislada no anula overrides heredados: revísalos/retíralos primero.</p><p>Analytics guarda agregados con escritor propio: cola actual 1.024, lotes 128 y flush de 10 s. El archivo vecino <code>*.pending.json</code> deriva de la ruta de su base. El arranque reproduce lotes con ID y retira el archivo antes de que <code>ready</code> admita trabajo. Recuperación ilegible/mayor de 16 MiB, base indisponible o fallo al retirar archivo mantienen admisión deshabilitada. Conserva base y archivo, revisa <code>ready</code>/pendientes/errores y respalda antes de reparar. No borres evidencia pendiente para aparentar salud; los diarios de puntos tienen otro contrato durable.</p><p><code>system.info</code> informa home/dataDir efectivos; resuelve los demás directorios con el entorno real de lanzamiento del host, no otra terminal. Usa <code>system.health</code> para ready/pendientes analíticos y contadores de ingreso LIVE.</p>`,18)])])}const b=a(o,[["render",t]]);export{h as __pageData,b as default};
